  /* رفع باگ: پیش‌تر این‌جا «DB.examTraps = [...]» بود و ۱۳ تلهٔ غنیِ
     database.js (با کلیدهای title/pattern/wrong/correct/relatedTags) را
     کامل پاک می‌کرد. چون شکل جدید هیچ relatedTags نداشت،
     Inference.detectExamTraps() همیشه [] برمی‌گرداند و بخش «تله‌های
     امتحانی مرتبط» در فاز ۵ هرگز نمایش داده نمی‌شد. اکنون افزودنی است
     (با گارد ددآپ روی trap و title) و هر ورودی relatedTags دارد. */
  if (!Array.isArray(DB.examTraps)) DB.examTraps = [];
  FIELD_TRAPS.forEach(t => {
    const dup = DB.examTraps.some(x =>
      (x.trap && t.trap && x.trap === t.trap) ||
      (x.title && t.title && x.title === t.title));
    if (!dup) DB.examTraps.push(t);
  });

